import React from 'react';
import { motion } from 'framer-motion';
import { useInView } from 'react-intersection-observer';
import { Brain, Database, Code, BarChart, Cpu, Target, Award, BookOpen, Briefcase } from 'lucide-react';

const About = () => {
  const [ref, inView] = useInView({
    triggerOnce: true,
    threshold: 0.1,
  });

  const interests = [
    {
      icon: Brain,
      title: 'Machine Learning',
      description: 'Building intelligent systems that learn from data and make predictions',
      color: 'from-purple-500 to-pink-500',
    },
    {
      icon: Database,
      title: 'Data Science',
      description: 'Extracting valuable insights from complex datasets using statistical methods',
      color: 'from-blue-500 to-cyan-500',
    },
    {
      icon: Code,
      title: 'Applied AI',
      description: 'Developing practical AI solutions for real-world business challenges',
      color: 'from-green-500 to-teal-500',
    },
    {
      icon: BarChart,
      title: 'Analytics',
      description: 'Creating data visualizations and dashboards for informed decision-making',
      color: 'from-orange-500 to-red-500',
    },
    {
      icon: Cpu,
      title: 'Deep Learning',
      description: 'Exploring neural networks and advanced AI architectures',
      color: 'from-indigo-500 to-purple-500',
    },
    {
      icon: Target,
      title: 'Problem Solving',
      description: 'Tackling complex challenges with analytical thinking and creativity',
      color: 'from-pink-500 to-rose-500',
    },
  ];

  const stats = [
    {
      icon: Code,
      value: '10+',
      label: 'Projects Completed',
      color: 'from-blue-500 to-cyan-500',
    },
    {
      icon: Award,
      value: '3+',
      label: 'Certifications',
      color: 'from-purple-500 to-pink-500',
    },
    {
      icon: BookOpen,
      value: '1',
      label: 'Research Publications',
      color: 'from-green-500 to-teal-500',
    },
    {
      icon: Briefcase,
      value: '1',
      label: 'Internship Experience',
      color: 'from-orange-500 to-red-500',
    },
  ];

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
      },
    },
  };

  const itemVariants = {
    hidden: { opacity: 0, translateY: 20 },
    visible: {
      opacity: 1,
      translateY: 0,
      transition: {
        duration: 0.5,
      },
    },
  };

  return (
    <section id="about" className="py-20 relative">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          ref={ref}
          initial="hidden"
          animate={inView ? 'visible' : 'hidden'}
          variants={containerVariants}
        >
          {/* Section Header */}
          <motion.div variants={itemVariants} className="text-center mb-16">
            <h2 className="section-title">About Me</h2>
            <p className="section-subtitle max-w-2xl mx-auto">
              Passionate about transforming data into insights and building intelligent solutions
            </p>
          </motion.div>

          {/* Main Content */}
          <div className="grid lg:grid-cols-2 gap-12 mb-16">
            {/* Left Column - Bio */}
            <motion.div variants={itemVariants} className="space-y-6">
              <div className="glass-card p-8">
                <h3 className="text-2xl font-bold mb-4 gradient-text">
                  Data Scientist & AI/ML Engineer
                </h3>
                <p className="text-gray-300 leading-relaxed mb-4">
                  Aspiring Data Scientist and AI/ML Engineer experienced in building end-to-end solutions, 
                  from churn prediction engines to real-time computer vision pipelines. 
                  
                </p>
                <p className="text-gray-300 leading-relaxed mb-4">
                  Proficient in Python, SQL, and the full Data Science lifecycle, including EDA, feature engineering, 
                  and model optimization. Proven ability to deploy scalable applications using FastAPI, Streamlit, 
                  to solve high-impact business problems.
                </p>
                <p className="text-gray-300 leading-relaxed">
                  Engineering student passionate about Data Science, Machine Learning, Applied AI, and Analytics. 
                  contributing to open-source projects, or sharing knowledge through technical writing.
                </p>
              </div>
            </motion.div>

            {/* Right Column - Interests Grid */}
            <motion.div variants={itemVariants}>
              <div className="grid grid-cols-2 gap-4">
                {interests.map((interest) => (
                  <div
                    key={interest.title}
                    className="glass-card p-6 hover:scale-105 transition-transform duration-300"
                  >
                    <div className={`inline-flex p-3 rounded-lg bg-gradient-to-r ${interest.color} mb-4`}>
                      <interest.icon className="w-6 h-6 text-white" />
                    </div>
                    <h4 className="text-lg font-semibold mb-2">{interest.title}</h4>
                    <p className="text-sm text-gray-400">{interest.description}</p>
                  </div>
                ))}
              </div>
            </motion.div>
          </div>

          {/* Stats */}
          <motion.div variants={itemVariants} className="mt-16">
            <h3 className="text-2xl font-bold mb-8 gradient-text text-center">
              Key Achievements
            </h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
              {stats.map((stat, index) => (
                <motion.div
                  key={stat.label}
                  variants={itemVariants}
                  className="glass-card p-6 text-center hover:scale-105 transition-transform duration-300"
                >
                  <div className={`inline-flex p-3 rounded-lg bg-gradient-to-r ${stat.color} mb-4`}>
                    <stat.icon className="w-6 h-6 text-white" />
                  </div>
                  <div className="text-3xl font-bold mb-2 gradient-text">{stat.value}</div>
                  <div className="text-sm text-gray-400">{stat.label}</div>
                </motion.div>
              ))}
            </div>
          </motion.div>
        </motion.div>
      </div>
    </section>
  );
};

export default About;
